23	export interface PostMergeSignals {
24	  /** The parent WorkItem this merged PR is linked to, if any (from PARENT_ISSUE_TAG). */
25	  parentIssue: number | undefined;
26	  /** Is the parent already closed (e.g. GitHub's native "Closes #N" auto-close already succeeded)? */
27	  parentAlreadyClosed: boolean;
28	  /** The agent that originally created this PR, if tagged (from ORIGIN_AGENT_TAG). */
29	  originAgent: string | undefined;
30	}
31	
32	/**
33	 * Decides what should happen to the parent WorkItem right after a PR
34	 * merges:
35	 *
36	 *   1. no linked parent at all -> nothing to do.
37	 *   2. the parent is already closed (native auto-close beat us to it) ->
38	 *      nothing to do -- re-invoking an agent to close an already-closed
39	 *      issue would be a pointless extra LLM call AND risks racing
40	 *      lib/aggregation.ts's idempotency marker against an independent
41	 *      event-driven aggregation path for the exact same completion.
42	 *   3. an origin agent is tagged -> prefer re-invoking THEM to confirm and
43	 *      close (they get a chance to give a final summary). The caller is
44	 *      still responsible for falling back to closing directly if that
45	 *      dispatch attempt itself fails -- this decision only expresses the
46	 *      PREFERRED handoff, not the outcome of attempting it.
47	 *   4. no origin agent tagged -> close the parent directly ourselves.
48	 */
49	export function decidePostMergeHandoff(signals: PostMergeSignals): PostMergeHandoff {
50	  if (signals.parentIssue === undefined) return { kind: "no-parent" };
51	  if (signals.parentAlreadyClosed) return { kind: "already-closed", parentIssue: signals.parentIssue };
52	  if (signals.originAgent) {
53	    return { kind: "reinvoke-origin-agent", parentIssue: signals.parentIssue, agent: signals.originAgent };
54	  }
55	  return { kind: "close-directly", parentIssue: signals.parentIssue };
56	}

